blocks.content:
1/* Blog Section Styling - Same as Hero */
2.blogs {
3    display: flex;
4    flex-direction: column;
5    align-items: center;
6    justify-content: center;
7    gap: 32px;
8    padding: 80px;
9    text-align: center;
10    background-color: #d1c4e9;    /* Same background color as Hero section */
11}
12
13/* Card Container */
14.card-row {
15    display: flex;
16    flex-wrap: wrap;    /* Allow the cards to wrap on smaller screens */
17    justify-content: center;    /* Center the cards horizontally */
18    gap: 20px;    /* Space between the cards */
19    margin: 40px auto;    /* Center the container */
20    padding: 0 20px;    /* Padding on the sides */
21    max-width: 1200px;    /* Ensure it doesn't stretch too wide */
22}
23
24/* Blog card styling */
25.card {
26    background-color: white;
27    border-radius: 8px;    /* Rounded corners */
28    box-shadow: 0 3px 4px rgba(0, 0, 0, 0.1);    /* Subtle shadow */
29    width: 300px;    /* Fixed width */
30    text-align: center;
31    display: flex;
32    flex-direction: column;    /* Stack content vertically */
33    gap: 4px;    /* Small gap between content */
34    align-items: center;
35    padding: 24px 0;    /* Adds padding */
36}
37
38/* Blog card image */
39.card img {
40    border-radius: 50%;    /* Circular image */
41    width: 192px;
42    height: 192px;
43    object-fit: cover;    /* Ensures image fits the circle */
44    margin-bottom: 16px;    /* Space below the image */
45}
46
47/* Blog card title */
48.card h3 {
49    color: #25265e;
50    font-weight: 700;
51    font-size: max(1vw, 18px);
52    text-decoration: none;
53}
54
55/* Blog card source */
56.card p {
57    font-size: 1rem;
58    color: #444576;
59}
60
61/* Read button */
62.card button {
63    padding: 8px 30px;
64    background-color: #0556f3;    /* Button background color */
65    color: white;    /* Button text color */
66    border: none;
67    border-radius: 4px;
68    cursor: pointer;
69    margin-top: 24px;
70}
71
72/* Button hover effect */
73.card button:hover {
74    background-color: #6c6ce5;    /* Button color on hover */
75}
